﻿import React from 'react';
import {AbsoluteFill,interpolateColors} from 'remotion';
import {useS,T,en,DUR,Easing,interpolate,clamp,FONT,Destello,golpe} from './kit';
// DINERO 2026-11-28 09:00 "La bolsa que trae menos" (reduflación). 2.5D: Vol (luz y sombra), 3 capas con parallax, giro leve, sombra en el suelo.
export const SUBS={arriba:860,size:84,acento:'#FFC83D'};
const A=[0,10,23,45,60,82,100,126].map(T);
const SB=A.map((t,i)=>i?t-.2:0),SE=[...SB.slice(1),DUR];
const e=(w:string,n=1)=>en(w,n)-.2; // la imagen entra 0,2 s antes de la palabra
const q=(s:number,a:number,b:number)=>interpolate(s,[a,Math.max(a+.01,b)],[0,1],{...clamp,easing:Easing.inOut(Easing.cubic)});
const lin=(s:number,a:number,b:number)=>Math.max(0,Math.min(1,(s-a)/Math.max(.01,b-a)));
const pop=(s:number,t:number,d=.4)=>{const u=lin(s,t,t+d);return u===0?0:Easing.out(Easing.back(2.2))(u);};
const ell=(cx:number,cy:number,rx:number,ry:number)=>`M${cx-rx} ${cy}a${rx} ${ry} 0 1 0 ${2*rx} 0a${rx} ${ry} 0 1 0 ${-2*rx} 0Z`;
const caps=(x1:number,y1:number,x2:number,y2:number,w:number)=>{const a=Math.atan2(y2-y1,x2-x1),r=w/2,nx=-Math.sin(a)*r,ny=Math.cos(a)*r;
 return `M${x1+nx} ${y1+ny}L${x2+nx} ${y2+ny}A${r} ${r} 0 0 0 ${x2-nx} ${y2-ny}L${x1-nx} ${y1-ny}A${r} ${r} 0 0 0 ${x1+nx} ${y1+ny}Z`;};
type C3=[string,string,string];
const OR='#FF7A1A',GO='#FFC83D',RO='#FF4D4D';
const SKIN:C3=['#f6cfa9','#c98a5c','#7c4527'],HAIR:C3=['#5a4644','#231414','#070202'];
const ORG:C3=['#ffc58a','#ff7a1a','#b23e00'],GLD:C3=['#fff1a8','#ffc83d','#a86a00'],RED:C3=['#ff9a9a','#ff4d4d','#8a1010'],SIL:C3=['#ffffff','#c4ccd6','#6c7886'],BLU:C3=['#8fb4ff','#1e5bff','#0a2a8a'],TQC:C3=['#a8f5ec','#19c3b3','#08645c'],WHT:C3=['#ffffff','#eef2f7','#aab6c6'],GRN:C3=['#bff5c8','#3ecb6a','#12602a'],PNK:C3=['#ffd0ea','#ff6fb5','#a8185e'],BRN:C3=['#e0a070','#8a4a22','#3a1a08'];
const Vol:React.FC<{id:string;d:string;c:C3;sw?:number;o?:number;borde?:string}>=({id,d,c,sw=70,o=24,borde})=><g>
 <defs><clipPath id={id}><path d={d}/></clipPath></defs>
 <path d={d} fill={c[1]}/>
 <g clipPath={`url(#${id})`}>
  <path d={d} fill='none' stroke={c[2]} strokeWidth={sw} filter='url(#b18)' transform={`translate(${-o} ${-o})`}/>
  <path d={d} fill='none' stroke={c[0]} strokeWidth={sw*.75} filter='url(#b18)' transform={`translate(${o} ${o})`}/>
 </g>
 <path d={d} fill='none' stroke={borde||c[2]} strokeWidth={3} opacity={.55}/>
</g>;
const Brillo2:React.FC<{x:number;y:number;rx:number;ry:number;r?:number;o?:number}>=({x,y,rx,ry,r=-30,o=.75})=><ellipse cx={x} cy={y} rx={rx} ry={ry} transform={`rotate(${r} ${x} ${y})`} fill='#fff' opacity={o} filter='url(#b6)'/>;
const Defs:React.FC=()=><defs>
 <filter id='b6' x='-50%' y='-50%' width='200%' height='200%'><feGaussianBlur stdDeviation='6'/></filter>
 <filter id='b18' x='-50%' y='-50%' width='200%' height='200%'><feGaussianBlur stdDeviation='18'/></filter>
 <filter id='b40' x='-50%' y='-50%' width='200%' height='200%'><feGaussianBlur stdDeviation='40'/></filter>
 <radialGradient id='chipG' cx='.35' cy='.3'><stop stopColor='#fff3a6'/><stop offset='.6' stopColor='#f5b82e'/><stop offset='1' stopColor='#b8730a'/></radialGradient>
 <linearGradient id='yel' x1='0' y1='0' x2='0' y2='1'><stop stopColor='#fff0a0'/><stop offset='.5' stopColor='#ffd23f'/><stop offset='1' stopColor='#d99a00'/></linearGradient>
 <radialGradient id='hondo' cx='.5' cy='.35'><stop stopColor='#3a1400'/><stop offset='1' stopColor='#080100'/></radialGradient>
 <radialGradient id='luz'><stop stopColor='#ffffff' stopOpacity='.55'/><stop offset='1' stopColor='#ffffff' stopOpacity='0'/></radialGradient>
 <linearGradient id='oroT' x1='0' y1='0' x2='0' y2='1'><stop stopColor='#ffffff'/><stop offset='.5' stopColor='#ffe27a'/><stop offset='1' stopColor='#e0a000'/></linearGradient>
 </defs>;
const Sh:React.FC<{x:number;y:number;rx:number;ry:number;o?:number}>=({x,y,rx,ry,o=.35})=><ellipse cx={x} cy={y} rx={rx} ry={ry} fill='#000' opacity={o} filter='url(#b18)'/>;
const Star:React.FC<{x:number;y:number;r:number;o?:number;c?:string}>=({x,y,r,o=1,c='#fff'})=><path d={`M${x} ${y-r}Q${x} ${y} ${x+r} ${y}Q${x} ${y} ${x} ${y+r}Q${x} ${y} ${x-r} ${y}Q${x} ${y} ${x} ${y-r}Z`} fill={c} opacity={o}/>;
const Cartel:React.FC<{x:number;y:number;t:string;w?:number;size?:number;c?:string;bg?:string;k?:number}>=({x,y,t,w=300,size=46,c=GO,bg='#14002a',k=1})=><g transform={`translate(${x} ${y}) scale(${k})`}><rect x={-w/2} y={-38} width={w} height={84} rx={22} fill='#000' opacity={.35} filter='url(#b6)'/><rect x={-w/2} y={-44} width={w} height={84} rx={22} fill={bg} stroke={c} strokeWidth={6}/><text y={14} textAnchor='middle' fill={c} fontSize={size} fontWeight={900}>{t}</text></g>;
const Txt3D:React.FC<{t:string;x:number;y:number;size:number;c?:string;edge?:string;ln?:string}>=({t,x,y,size,c='#fff',edge='#8a5a00',ln=GO})=><g textAnchor='middle' fontWeight={900} fontSize={size}>
 {[12,9,6,3].map(d=><text key={d} x={x+d*.5} y={y+d} fill={edge} stroke={edge} strokeWidth={size*.12} strokeLinejoin='round'>{t}</text>)}
 <text x={x} y={y} fill={c} stroke={ln} strokeWidth={size*.07} strokeLinejoin='round' paintOrder='stroke'>{t}</text>
 <text x={x-2} y={y-size*.06} fill='#fff' opacity={.45} clipPath='none' fontSize={size}>{t}</text>
</g>;
// Flecha con volumen de (x1,y1) a (x2,y2)
const Flecha:React.FC<{id:string;x1:number;y1:number;x2:number;y2:number;c?:C3;w?:number}>=({id,x1,y1,x2,y2,c=GLD,w=30})=>{const a=Math.atan2(y2-y1,x2-x1),hx=x2-Math.cos(a)*w*2.2,hy=y2-Math.sin(a)*w*2.2,nx=-Math.sin(a)*w*1.3,ny=Math.cos(a)*w*1.3;
 return <g><Vol id={id+'s'} d={caps(x1,y1,hx,hy,w)} c={c} sw={w*.8} o={w*.3}/><Vol id={id+'h'} d={`M${x2} ${y2}L${hx+nx} ${hy+ny}L${hx-nx} ${hy-ny}Z`} c={c} sw={w} o={w*.2}/></g>;};
// Papita: pieza propia con gradiente (volumen), sombra, nervaduras y brillo
const CHIP='M-34 -4C-36 -24 -10 -34 10 -30C32 -26 42 -6 34 14C26 34 -6 36 -24 24C-32 18 -34 6 -34 -4Z';
const Chip:React.FC<{x:number;y:number;r?:number;k?:number;o?:number;glow?:string}>=({x,y,r=0,k=1,o=1,glow})=><g transform={`translate(${x} ${y}) rotate(${r}) scale(${k})`} opacity={o}>
 {glow&&<circle r={52} fill={glow} opacity={.55} filter='url(#b6)'/>}
 <path d={CHIP} transform='translate(5 8)' fill='#000' opacity={.3}/>
 <path d={CHIP} fill='url(#chipG)' stroke='#a8680a' strokeWidth={3}/>
 <path d='M-22 -8Q0 -20 24 -8M-18 8Q2 -2 26 8' stroke='#fff3a6' strokeWidth={3} fill='none' opacity={.8}/>
 <circle cx={-10} cy={14} r={2.5} fill='#8a4a06'/><circle cx={20} cy={10} r={2.5} fill='#8a4a06'/>
 <ellipse cx={-14} cy={-14} rx={9} ry={4} fill='#fff' opacity={.6} transform='rotate(-20 -14 -14)'/>
</g>;
const Pile:React.FC<{ytop:number;ybot:number;x0:number;x1:number;seed?:number}>=({ytop,ybot,x0,x1,seed=0})=>{const out:React.ReactNode[]=[];const rows=Math.ceil((ybot-ytop)/24)+1,n=Math.floor((x1-x0)/52);
 for(let r=0;r<rows;r++)for(let c=0;c<=n;c++){const jx=((c*37+r*53+seed*17)%23)-11,jy=((c*29+r*41+seed*13)%15)-7;out.push(<Chip key={r+'_'+c} x={x0+c*52+(r%2)*26+jx} y={Math.max(ytop+10,ybot-r*24+jy)} r={((c*71+r*37+seed*11)%160)-80} k={.82}/>);}
 return <>{out}</>;};
// Bolsa de papitas metalizada: naranja con franja amarilla, sol y PAPITAS (sin marca real). glass=transparente con nivel, boca=abierta, wr=arrugas, ala=plástico estirado.
const BAG='M-150 -205C-172 -100 -170 100 -150 205L150 205C170 100 172 -100 150 -205Z';
const CR_T='M-152 -207'+'q6.08 -7 12.16 0'.repeat(25)+'V-165H-152Z',CR_B='M-152 165H152V207'+'q-6.08 7 -12.16 0'.repeat(25)+'Z';
const Bolsa:React.FC<{id:string;s?:number;x:number;y:number;k?:number;r?:number;sx?:number;sy?:number;glass?:number;lvl?:number;boca?:number;ala?:number;wr?:number;o?:number;children?:React.ReactNode}>=({id,s=0,x,y,k=1,r=0,sx=1,sy=1,glass=0,lvl=.5,boca=0,ala=0,wr=0,o=1,children})=>{
 const lv=190-lvl*380;
 return <g transform={`translate(${x} ${y}) rotate(${r}) scale(${k*sx} ${k*sy})`} opacity={o}>
 <Sh x={10} y={238} rx={175} ry={26}/>
 <defs><clipPath id={id+'c'}><path d={BAG}/></clipPath></defs>
 {glass>0&&<g opacity={glass}>
  <path d={BAG} fill='#1a0a00' opacity={.6}/>
  <g clipPath={`url(#${id}c)`}>
   <ellipse cy={lv-110} rx={120} ry={90} fill='#9fe8ff' opacity={.14} filter='url(#b18)'/>
   {[0,1,2,3,4,5,6].map(j=><circle key={j} cx={-100+((j*61)%200)+Math.sin(s*1.7+j)*10} cy={-170+((j*47)%Math.max(30,lv+150))+Math.cos(s*1.3+j)*8} r={4+j%3} fill='#fff' opacity={.35+.35*Math.sin(s*3+j*2)}/>)}
   <Pile ytop={lv} ybot={200} x0={-135} x1={135} seed={2}/>
   <path d={`M-160 ${lv}H160`} stroke={GO} strokeWidth={5} strokeDasharray='16 10'/>
  </g>
 </g>}
 <g opacity={1-glass*.93}>
  <Vol id={id+'v'} d={BAG} c={ORG} sw={110} o={34}/>
  <g clipPath={`url(#${id}c)`}>
   <path d='M-180 25L180 -70V35L-180 130Z' fill='url(#yel)'/>
   <path d='M-180 25L180 -70' stroke='#fff6c0' strokeWidth={5} opacity={.8}/><path d='M-180 130L180 35' stroke='#b27a00' strokeWidth={6} opacity={.5}/>
   {['M-150 -150Q-90 -110 -135 -40','M150 -120Q100 -70 140 -10','M-155 150Q-80 170 -130 200','M120 150Q60 190 140 205'].map((d,j)=><path key={j} d={d} stroke='#8a2c00' strokeWidth={10} fill='none' opacity={.32} filter='url(#b6)'/>)}
   {wr>0&&['M-120 -60Q-40 -20 -110 20','M110 -40Q40 10 120 60','M-60 -140Q10 -100 -50 -60','M70 120Q0 150 60 190','M-140 90Q-70 120 -150 160','M20 -90Q80 -50 30 -10'].map((d,j)=><path key={'w'+j} d={d} stroke='#6a1c00' strokeWidth={9} fill='none' opacity={wr*.45} filter='url(#b6)'/>)}
  </g>
  <g transform='translate(0 -112)'>{Array.from({length:12}).map((_,j)=><path key={j} d='M-9 -62L0 -88L9 -62Z' fill={GO} stroke='#a86a00' strokeWidth={2} transform={`rotate(${j*30})`}/>)}<circle r={52} fill='url(#chipG)' stroke='#a86a00' strokeWidth={4}/><circle cx={-14} cy={-16} r={14} fill='#fff' opacity={.5}/></g>
  <text transform='translate(3 36) rotate(-14)' textAnchor='middle' fontSize={50} fontWeight={900} fill='#fff' stroke='#7a1d00' strokeWidth={7} paintOrder='stroke'>PAPITAS</text>
  {boca===0&&<><Vol id={id+'t'} d={CR_T} c={['#ffd9b0','#ff9a40','#c24a08']} sw={24} o={8}/><Vol id={id+'u'} d={CR_B} c={['#ffd9b0','#ff9a40','#c24a08']} sw={24} o={8}/>
   {Array.from({length:24}).map((_,j)=><g key={j}><path d={`M${-140+j*12.2} -205V-165M${-140+j*12.2} 168V205`} stroke='#fff' strokeWidth={2} opacity={.4}/></g>)}</>}
  {boca>0&&<Vol id={id+'u'} d={CR_B} c={['#ffd9b0','#ff9a40','#c24a08']} sw={24} o={8}/>}
  <Brillo2 x={-112} y={-70} rx={14} ry={92} r={4} o={.75}/><Brillo2 x={108} y={70} rx={10} ry={62} r={-4} o={.55}/><Brillo2 x={-40} y={-195} rx={80} ry={8} r={-3} o={.7}/>
 </g>
 {boca>0&&<g transform='translate(0 -203)'>
  <defs><clipPath id={id+'m'}><ellipse rx={150*boca} ry={76*boca}/></clipPath></defs>
  <ellipse rx={150*boca} ry={76*boca} fill='url(#hondo)'/>
  <g clipPath={`url(#${id}m)`}>
   <ellipse cy={-34} rx={100} ry={26} fill='#9fe8ff' opacity={.2} filter='url(#b18)'/>
   {[0,1,2,3,4,5,6,7].map(j=><circle key={j} cx={((j*83)%250)-125} cy={-54+((j*37)%46)} r={3+j%3} fill='#fff' opacity={.35+.55*Math.max(0,Math.sin(s*5+j*1.7))}/>)}
   <g transform='translate(0 10) scale(.78)'><Pile ytop={12} ybot={120} x0={-190} x1={190} seed={3}/></g>
  </g>
  <ellipse rx={150*boca} ry={76*boca} fill='none' stroke='#ff9a40' strokeWidth={13}/><ellipse rx={150*boca-5} ry={76*boca-3} fill='none' stroke='#fff' strokeWidth={3} opacity={.55}/>
 </g>}
 {ala>0&&<g><path d={`M118 -214L${150+110*ala} ${-215-130*ala}L172 -188Z`} fill='#ffb877' stroke={OR} strokeWidth={4} opacity={.95}/><path d={`M135 -205L${150+100*ala} ${-210-120*ala}`} stroke='#fff' strokeWidth={4} opacity={.7}/></g>}
 {children}
 </g>;};
// Mano que pellizca (pulgar e índice con volumen, nudillos, uñas); la punta de los dedos queda en (0,0), el brazo sale a la derecha.
const Dedo:React.FC<{id:string;a:[number,number];b:[number,number];w?:number;nail?:boolean;c?:C3}>=({id,a,b,w=44,nail=true,c=SKIN})=>{const ang=Math.atan2(b[1]-a[1],b[0]-a[0]),deg=ang*180/Math.PI,px=-Math.sin(ang)*w*.28,py=Math.cos(ang)*w*.28;
 return <g><Vol id={id} d={caps(a[0],a[1],b[0],b[1],w)} c={c} sw={w*.8} o={w*.25}/>
 {[.45,.72].map((u,j)=>{const mx=a[0]+(b[0]-a[0])*u,my=a[1]+(b[1]-a[1])*u;return <path key={j} d={`M${mx-px} ${my-py}L${mx+px} ${my+py}`} stroke={c[2]} strokeWidth={3} opacity={.5}/>;})}
 {nail&&<g transform={`translate(${b[0]} ${b[1]}) rotate(${deg})`}><ellipse cx={-w*.3} rx={w*.34} ry={w*.3} fill='#ffe3d6' stroke={c[2]} strokeWidth={2}/><ellipse cx={-w*.38} cy={-w*.1} rx={w*.14} ry={w*.07} fill='#fff' opacity={.85}/></g>}</g>;};
const Pinza:React.FC<{id:string}>=({id})=><g>
 <Vol id={id+'ar'} d={caps(330,60,660,300,140)} c={SKIN} sw={50} o={14}/>
 <Vol id={id+'sl'} d={caps(540,210,780,390,210)} c={TQC} sw={60} o={16}/>
 <Vol id={id+'pa'} d='M120 -60C200 -110 300 -90 335 -20C355 50 325 130 245 150C165 165 110 110 100 50C95 0 100 -35 120 -60Z' c={SKIN} sw={50} o={14}/>
 {[[300,-20],[330,36],[312,92]].map(([x,y],j)=><Vol key={j} id={id+'k'+j} d={ell(x,y,36,30)} c={SKIN} sw={26} o={8}/>)}
 <Dedo id={id+'ix'} a={[210,-50]} b={[6,-12]} w={44}/><Dedo id={id+'th'} a={[200,105]} b={[6,16]} w={50}/>
</g>;
// Mano que sostiene (dedos y pulgar rodean el objeto que va en children, brazo y manga abajo)
const Sost:React.FC<{id:string;x:number;y:number;k?:number;r?:number;gy?:number;children:React.ReactNode}>=({id,x,y,k=1,r=0,gy=95,children})=><g transform={`translate(${x} ${y}) rotate(${r}) scale(${k})`}>
 <Vol id={id+'a1'} d={caps(40,900,10,260,150)} c={SKIN} sw={50} o={14}/>
 <Vol id={id+'a2'} d={caps(70,1100,40,560,215)} c={TQC} sw={70} o={20}/>
 <Vol id={id+'pm'} d='M-110 150C-60 100 80 100 120 160C140 240 100 330 20 340C-70 345 -130 270 -110 150Z' c={SKIN} sw={50} o={14}/>
 {children}
 {[0,1,2,3].map(j=><Dedo key={j} id={id+'f'+j} a={[-205,gy+j*46-72]} b={[-72,gy+j*46-82]} w={42}/>)}
 <Dedo id={id+'th'} a={[215,gy-20]} b={[78,gy-52]} w={50}/>
</g>;
// Puño: índice señalando o pulgar arriba
const Puno:React.FC<{id:string;x:number;y:number;k?:number;r?:number;pose:'senala'|'pulgar';p?:number}>=({id,x,y,k=1,r=0,pose,p=1})=><g transform={`translate(${x} ${y}) rotate(${r}) scale(${k})`}>
 <Vol id={id+'a'} d={caps(0,950,0,200,150)} c={SKIN} sw={50} o={14}/>
 <Vol id={id+'sl'} d={caps(0,1100,0,560,215)} c={TQC} sw={70} o={20}/>
 <Vol id={id+'f'} d='M-100 -10C-100 -90 -40 -110 0 -110C55 -110 105 -85 105 -10C108 70 85 140 0 160C-85 145 -105 70 -100 -10Z' c={SKIN} sw={60} o={18}/>
 {(pose==='senala'?[35,85,135]:[-5,45,95,145]).map((y0,j)=><Dedo key={j} id={id+'r'+j} a={[-80,y0]} b={[78,y0-10]} w={46} nail={false}/>)}
 {pose==='senala'?<><Dedo id={id+'ix'} a={[-52,-40]} b={[-60,-40-300*p]} w={50}/><Dedo id={id+'th'} a={[88,75]} b={[10,40]} w={52}/></>:<Dedo id={id+'th'} a={[52,-30]} b={[54,-30-190*p]} w={60}/>}
</g>;
// Carla: piel canela, rizos recogidos en moño, camiseta turquesa, ojos con punto blanco, cejas expresivas
const Cara:React.FC<{s:number;id:string;x?:number;y?:number;k?:number;look?:[number,number];cL?:number;cR?:number;sonr?:number;blink?:number}>=({s,id,x=540,y=1000,k=1,look=[0,0],cL=0,cR=0,sonr=0,blink=0})=><g transform={`translate(${x} ${y+Math.sin(s*1.4)*6}) scale(${k})`}>
 <Sh x={0} y={625} rx={300} ry={50} o={.3}/>
 <Vol id={id+'n'} d='M-62 170L-72 310L72 310L62 170Z' c={SKIN} sw={40} o={12}/>
 <Vol id={id+'t'} d='M-270 640C-262 400 -190 300 -72 275L0 330L72 275C190 300 262 400 270 640Z' c={TQC} sw={120} o={34}/>
 <path d='M-30 330L-38 430M30 330L38 430' stroke='#fff' strokeWidth={7} strokeLinecap='round'/>
 {[-1,1].map(j=><g key={j}><Vol id={id+'e'+j} d={ell(j*182,10,32,52)} c={SKIN} sw={26} o={8}/><circle cx={j*184} cy={78} r={17} fill='none' stroke={GO} strokeWidth={6}/></g>)}
 <Vol id={id+'b'} d={ell(0,-300,92,82)} c={HAIR} sw={50} o={16}/>
 {[0,1,2,3,4,5].map(j=><path key={j} d={`M${-70+j*28} ${-345+Math.abs(j-2.5)*8}Q${-60+j*28} ${-300} ${-50+j*28} ${-258}`} stroke={HAIR[0]} strokeWidth={5} fill='none' opacity={.55}/>)}
 <Vol id={id+'h'} d='M0 -250C120 -250 185 -150 182 -20C180 110 110 215 0 232C-110 215 -180 110 -182 -20C-185 -150 -120 -250 0 -250Z' c={SKIN} sw={130} o={36}/>
 {[-1,1].map(j=><ellipse key={j} cx={j*95} cy={70} rx={48} ry={30} fill='#ff8a8a' opacity={.3} filter='url(#b18)'/>)}
